"""Validate fresh final-source movies against the original matched comparison inputs."""
import pathlib,json,sys
results=pathlib.Path(sys.argv[1]);spec=json.loads(pathlib.Path(sys.argv[2]).read_text());selected=sys.argv[3].split(',');rows=json.loads((results/'matrix/results.json').read_text())['rows'];expected={r['fixture']:r for r in spec['expectedOriginalConditions']};fixtures={r['id']:r for r in spec['fixtures']};assert len(rows)==len(selected) and {r['fixture']['id'] for r in rows}==set(selected)
records=[]
for row in rows:
 case=row['fixture']['id'];old=expected[case];fav=row['provenance']['finalArtifactVerification'];binding=fav['binding'];assert row['status']=='PASS' and row['variant']=='v3';assert binding['sourceCommit']==spec['sourceCommit'] and binding['videoSHA256']==row['sha256'];assert fav['status']=='MEASURED';checks={'fixture':row['fixture']==fixtures[case],'input':row['input']==old['input'],'audioWAVSHA256':row['referenceInputs']['audioSHA256']==old['audioWAVSHA256'],'pcmHash':row['sourceInvariant']['pcmHash']==old['pcmHash'],'outputProfile':binding['outputProfile']==old['outputProfile']};records.append({'fixture':case,'videoSHA256':row['sha256'],'originalVideoSHA256':old['originalVideoSHA256'],'status':'MATCHED' if all(checks.values()) else 'CONFOUNDED','checks':checks,'actualBinding':binding,'lyricSafety':fav['status']})
report={'scope':'New natural-selection movies, not frozen-plan replay. Original matched main/previous input correspondence; no independent effect/artistic certification.','sourceCommit':spec['sourceCommit'],'records':records,'status':'MATCHED' if all(r['status']=='MATCHED' for r in records) else 'CONFOUNDED'};(results/'original-input-correspondence.json').write_text(json.dumps(report,indent=2)+'\n');print(report['status']);assert report['status']=='MATCHED'
